using Demo.Inventory;
class InventoryReader {
    static StockItem Sample() => new StockItem { Sku = "A-1", Quantity = 24, Labels = { "fragile" }, State = StockState.StockAvailable };
    static object Observe(StockItem item) => new { quantity = item.Quantity, labels = item.Labels, state = item.State };
    static bool CanFulfill(StockItem item, int requested) => item.Quantity >= requested && item.State == StockState.StockAvailable;
}

from generated.inventory_pb2 import StockItem, STOCK_AVAILABLE

def sample():
    return StockItem(sku="A-1", quantity=24, labels=["fragile"], state=STOCK_AVAILABLE)
def observe(item):
    return {"quantity": item.quantity, "labels": list(item.labels), "state": item.state}
def can_fulfill(item, requested):
    return item.quantity >= requested and item.state == STOCK_AVAILABLE

import { StockItem, StockState } from "./generated/inventory";
export const sample = () => StockItem.create({ sku: "A-1", quantity: 24, labels: ["fragile"], state: StockState.STOCK_AVAILABLE });
export const observe = (item: StockItem) => ({ quantity: item.quantity, labels: item.labels, state: item.state });
export const canFulfill = (item: StockItem, requested: number) => item.quantity >= requested && item.state === StockState.STOCK_AVAILABLE;
